+            assertEquals(leftAnchor, AnchorPane.getLeftAnchor(child), 0.0);
+            assertEquals(topAnchor, AnchorPane.getTopAnchor(child), 0.0);
+        } finally {
+            stage.hide();
+        }
+    }
